// Works out when each text should go, with quiet hours already applied, so every Wait below just waits.
const s = $('Your settings').first().json;
const b = $('Appointment booked').first().json.body || {};
const tz = s.timezone || 'America/New_York';
const now = DateTime.now().setZone(tz);

const digits = String(b.phone || '').replace(/\D/g, '');
const phone = digits.length === 10 ? '+1' + digits : (digits.length === 11 && digits[0] === '1' ? '+' + digits : '');
const appt = DateTime.fromISO(String(b.appointment_time || ''), { zone: tz });
const name = String(b.customer_name || '').trim();
const first = name.split(/\s+/)[0] || 'there';
const service = String(b.service || 'your appointment').trim();
const biz = String(s.business_name || 'us').trim();

const problems = [];
if (!phone) problems.push('phone "' + (b.phone || '') + '" is not a usable US mobile number');
if (!appt.isValid) problems.push('appointment_time "' + (b.appointment_time || '') + '" is not an ISO date and time');
else if (appt <= now) problems.push('the appointment time has already passed');

// Quiet hours. The window can wrap past midnight (20:00 to 08:00) or not (13:00 to 14:00).
const hm = (v, d) => { const p = String(v || d).split(':').map(Number); return [p[0] || 0, p[1] || 0]; };
const [qsH, qsM] = hm(s.quiet_start, '20:00');
const [qeH, qeM] = hm(s.quiet_end, '08:00');
const qs = qsH * 60 + qsM, qe = qeH * 60 + qeM;
const mins = d => d.hour * 60 + d.minute;
const inQuiet = d => qs === qe ? false : (qs > qe ? (mins(d) >= qs || mins(d) < qe) : (mins(d) >= qs && mins(d) < qe));
// Reminders move earlier, to 30 minutes before quiet hours start, so they still land before the appointment.
const earlier = d => {
  if (!inQuiet(d)) return d;
  let t = d.set({ hour: qsH, minute: qsM, second: 0, millisecond: 0 }).minus({ minutes: 30 });
  if (t > d) t = t.minus({ days: 1 });
  return t;
};
// The confirmation moves later, to when quiet hours end.
const later = d => {
  if (!inQuiet(d)) return d;
  let t = d.set({ hour: qeH, minute: qeM, second: 0, millisecond: 0 });
  if (t < d) t = t.plus({ days: 1 });
  return t;
};

const h1 = Number(s.reminder_1_hours) > 0 ? Number(s.reminder_1_hours) : 24;
const h2 = Number(s.reminder_2_hours) > 0 ? Number(s.reminder_2_hours) : 2;
// Two reminders squeezed together by quiet hours read like spam, so the second one is dropped
// unless it lands at least an hour after the first (or half the configured gap, if that is shorter).
const minGap = Math.min(60, Math.abs(h1 - h2) * 30);
const ok = problems.length === 0;
const soon = now.plus({ minutes: 5 });

const confAt = later(now);
const sendConf = ok && s.send_confirmation !== false && confAt < appt;
const r1 = ok ? earlier(appt.minus({ hours: h1 })) : now;
const sendR1 = ok && r1 > soon && (!sendConf || r1 > confAt);
const r2 = ok ? earlier(appt.minus({ hours: h2 })) : now;
const sendR2 = ok && r2 > soon && r2 < appt && (!sendConf || r2 > confAt) && (!sendR1 || r2.diff(r1, 'minutes').minutes >= minGap);

const when = at => {
  const days = appt.startOf('day').diff(at.startOf('day'), 'days').days;
  const time = appt.toFormat('h:mm a');
  if (days === 0) return 'today at ' + time;
  if (days === 1) return 'tomorrow at ' + time;
  return 'on ' + appt.toFormat('cccc, LLL d') + ' at ' + time;
};

const iso = d => d.toUTC().toISO();
return [{ json: {
  ok, problems: problems.join('; '), phone, name, service,
  appointment: ok ? appt.toFormat("cccc, LLL d 'at' h:mm a") : '',
  biz_number: s.business_number, owner_cell: s.owner_cell,
  confirm_at: iso(sendConf ? confAt : now), send_confirmation: sendConf,
  confirm_text: ok ? 'Hi ' + first + ", you're booked with " + biz + ' for ' + service + ' ' + when(confAt) + '. Reply here if you need to change it.' : '',
  reminder_1_at: iso(sendR1 ? r1 : now), send_reminder_1: sendR1,
  reminder_1_text: ok ? 'Reminder from ' + biz + ': ' + service + ' ' + when(r1) + '. Reply here if you need to reschedule.' : '',
  reminder_2_at: iso(sendR2 ? r2 : now), send_reminder_2: sendR2,
  reminder_2_text: ok ? 'See you soon, ' + first + ': ' + service + ' with ' + biz + ' ' + when(r2) + '.' : '',
  owner_text: 'Appointment reminders not set for ' + (name || 'a customer') + ': ' + problems.join('; ') + '.',
} }];
